import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.close();

        long count = 0;

        for (int a = 1; a <= n; a++) {
            for (int b = a; b <= n; b++) {
                int c = a ^ b;
                if (c < b) continue;
                if (c > n) continue;
                // Check triangle inequality: a + b > c (since a <= b <= c, other inequalities hold)
                if (a + b > c) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}
